from pathlib import Path

p=Path('apps/web/app/page.tsx')
s=p.read_text(encoding='utf-8')
s=s.replace("import {GridChart} from '@/components/grid-chart';", "import {GridChart} from '@/components/grid-chart';\nimport {LiveStatus} from '@/components/live-status';")
s=s.replace('const next=await api.next(); const race=next.data;', 'const [next,status]=await Promise.all([api.next(),api.status()]); const race=next.data;')
s=s.replace('<div className="home-content">', '<div className="home-source-status"><LiveStatus status={status.data}/></div><div className="home-content">')
s=s.replace('<span className="singapore-flag"/>', "{race.country==='Singapore'?<span className=\"singapore-flag\"/>:<Flag size={14}/>}")
s=s.replace('<Track/></div><div className="race-card-stats">', "{race.circuit_id==='marina_bay'?<Track/>:<div className=\"race-card-year mono\">{race.season}</div>}</div><div className=\"race-card-stats\">")
s=s.replace("<small>{race.is_demo?'SHOWCASE STATUS':'START TIME'}</small>", '<small>START TIME / UTC</small>')
s=s.replace('<Track/><span className="mono subtle-note">', "{race?.circuit_id==='marina_bay'&&<Track/>}<span className=\"mono subtle-note\">")
s=s.replace(' · SCHEMATIC</span>', ' · HISTORICAL SAMPLE</span>')
s=s.replace('version={pred.data.model_version}/><ForecastTable', 'version={pred.data.model_version}/><div className="forecast-method"><strong>{pred.data.method}</strong><p>{pred.data.notice}</p></div><ForecastTable')
p.write_text(s,encoding='utf-8')
p=Path('apps/web/app/methodology/page.tsx'); s=p.read_text(encoding='utf-8')
s=s.replace('Demo mode uses synthetic educational fixtures and illustrative probabilities. It does not report model accuracy or represent a current forecast.', 'Production views serve real saved data only. After practice, the current release uses an explicitly uncalibrated pace/form baseline; after qualifying it uses the evaluated model artifact. The practice baseline has not been validated as a calibrated winner model. Unavailable source data stays unavailable.')
s=s.replace('FastF1 ingestion is optional for verified session timing. OpenF1 and Open-Meteo are planned supplements;', 'FastF1 supplies published practice timing; Jolpica supplies qualifying classifications and race outcomes. Sources are polled in a separate worker every 15 minutes and open pages refresh every minute. Upstream publication delays can postpone forecasts. OpenF1 and Open-Meteo are planned supplements;')
p.write_text(s,encoding='utf-8')
p=Path('apps/web/components/session-tabs.tsx'); s=p.read_text(encoding='utf-8')
s=s.replace('<div className="pace-chart"', '<>{rows.length===0&&<div className="session-empty"><strong>{session?.status||"Awaiting data"}</strong><p>{session?.notice||"Timing appears after this session has ended and the source has published usable data."}</p></div>}<div className="pace-chart"')
s=s.replace('as zero.</p>', 'as zero.</p>')
s=s.replace('Missing laps are shown as unavailable.</p></div></div>;', 'Missing laps are shown as unavailable.</p></></div></div>;')
p.write_text(s,encoding='utf-8')
